/** Parses a calendar date such as "2026-03-31" to a Date at midnight UTC. */
export function parseIsoDate(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (match === null) throw new Error(`Not a calendar date: ${text}`);
  return new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
}

/** Returns the date a number of days later. */
export function addDays(date, days) {
  return new Date(date.getTime() + days * 86_400_000);
}
import { parseIsoDate } from './dates.js';
import { addCents } from './money.js';

const invoices = [
  {
    id: 'inv_1',
    customerId: 'cus_003',
    issuedOn: parseIsoDate('2026-03-31'),
    currency: 'EUR',
    lines: [{ description: 'Espresso beans, 1 kg', quantity: 2, unitPriceCents: 1850 }],
  },
  {
    id: 'inv_2',
    customerId: 'cus_002',
    issuedOn: parseIsoDate('2026-04-02'),
    currency: 'USD',
    lines: [
      { description: 'Grinder', quantity: 1, unitPriceCents: 12900 },
      { description: 'Filter papers', quantity: 3, unitPriceCents: 450 },
    ],
  },
];
let nextNumber = 3;

/** Returns the total of an invoice in cents. */
export function invoiceTotal(invoice) {
  return addCents(...invoice.lines.map((line) => line.quantity * line.unitPriceCents));
}

/** Creates an invoice for a customer, keeps it, and returns it. */
export function createInvoice({ customerId, lines, currency = 'EUR', issuedOn = new Date() }) {
  const invoice = { id: `inv_${nextNumber}`, customerId, issuedOn, currency, lines };
  nextNumber += 1;
  invoices.push(invoice);
  return invoice;
}

/** Returns every invoice. */
export function listInvoices() {
  return [...invoices];
}
import { findCustomer } from './customers.js';
import { createInvoice, invoiceTotal, listInvoices } from './invoices.js';

/** Answers one request, `{ method, path, body }`, with a response, `{ status, body }`. */
export function handle(request) {
  if (request.method === 'GET' && request.path === '/invoices') {
    return { status: 200, body: { invoices: listInvoices().map(toInvoiceBody) } };
  }
  if (request.method === 'POST' && request.path === '/invoices') {
    const { customerId, lines } = request.body ?? {};
    if (findCustomer(customerId) === undefined) return { status: 400, body: 'Unknown customer' };
    return { status: 201, body: toInvoiceBody(createInvoice({ customerId, lines })) };
  }
  return { status: 404, body: 'Not found' };
}

function toInvoiceBody(invoice) {
  return {
    id: invoice.id,
    customerId: invoice.customerId,
    issuedOn: invoice.issuedOn,
    currency: invoice.currency,
    totalCents: invoiceTotal(invoice),
  };
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { handle } from '../lib/routes.js';

test('lists the invoices with their totals', () => {
  const response = handle({ method: 'GET', path: '/invoices' });
  assert.equal(response.status, 200);
  assert.deepEqual(
    response.body.invoices.map((invoice) => [invoice.id, invoice.totalCents]),
    [
      ['inv_1', 3700],
      ['inv_2', 14250],
    ],
  );
});

test('creates an invoice for a known customer', () => {
  const lines = [{ description: 'Tamper', quantity: 1, unitPriceCents: 2500 }];
  const response = handle({ method: 'POST', path: '/invoices', body: { customerId: 'cus_003', lines } });
  assert.equal(response.status, 201);
  assert.equal(response.body.totalCents, 2500);
});

test('refuses an invoice for an unknown customer', () => {
  const response = handle({ method: 'POST', path: '/invoices', body: { customerId: 'cus_999', lines: [] } });
  assert.equal(response.status, 400);
});
import assert from 'node:assert/strict';
import test from 'node:test';
import { addDays, parseIsoDate } from '../lib/dates.js';

test('parses a calendar date to midnight UTC', () => {
  assert.equal(parseIsoDate('2026-03-31').toISOString(), '2026-03-31T00:00:00.000Z');
});

test('refuses text that is not a calendar date', () => {
  assert.throws(() => parseIsoDate('31/03/2026'));
});

test('adds days across the end of a month', () => {
  assert.equal(addDays(parseIsoDate('2026-03-31'), 1).toISOString(), '2026-04-01T00:00:00.000Z');
});
# invoice-service

Creates and lists the invoices of the shop's customers. It has no dependencies: it runs on Node.js 22 or later alone.

`npm test` runs the tests in `test/`.

| Path | Holds |
|---|---|
| `lib/routes.js` | The HTTP routes, as one function from a request to a response |
| `lib/invoices.js` | Invoices and their totals |
| `lib/customers.js` | The customers, read from `lib/data/customers.json` |
| `lib/money.js` | Amounts, in cents |
| `lib/dates.js` | Calendar dates |
| `lib/config.js` | Settings read from environment variables |
| `lib/legacy/tax.js` | Tax rates, from the old billing system |

